 const saved=await checkpointCache.get(generation);if(saved.revision!==result.revision||saved.campaignId!==result.campaign.id||saved.generation!==generation||JSON.stringify(saved.parameterNames)!==JSON.stringify(result.algorithm.parameters)||saved.parameters.length!==result.algorithm.parameters.length||!saved.tasks[taskName]?.frames?.length)throw Error(tr("检查点版本或参数不一致","Checkpoint version or parameters do not match"));
