 const form=$('#free-form');if(!cfg||!freeWorld)return;recoveryOption();$('#feedback-live').hidden=true;
 freeRunning=false;busy=false;runId++;worker?.terminate();worker=null;freeFrames=[];events=[];freeAccumulator=0;latestTiming=null;roundTrip=[];
