async function startFree(e){e?.preventDefault();const form=$('#free-form');if(!form.reportValidity()||busy)return;const values=Object.fromEntries(new FormData(form));freeCase=readInitialState();if(values.task==='stationary_kickflip'&&norm(freeCase.vel)>1e-9){$('#free-message').textContent=tr("原地零初速任务请把三个初速度都设为 0。","For a stationary zero-velocity task, set all three initial velocities to 0.");return}delete freeCase.initialClearance;freePolicy=values.policy;if(freePolicy==='v3_recovery'&&freeCase.task!=='moving_recovery'){$('#free-message').textContent=tr("倒置修复版仅用于任意姿态回正。","The inverted-recovery fix is only for arbitrary-attitude recovery.");return}const p=freePolicy==='v3_recovery'?recoveryManifest:result.tasks[freeCase.task].policies[freePolicy==='no_control'?'initial':freePolicy];if(!p){$('#free-message').textContent=tr("这个检查点尚未生成。","This checkpoint has not been generated yet.");return}freeConfig=structuredClone(freePolicy==='v3_recovery'?recoveryConfig:cfg);freeParameters=structuredClone(p.parameters);freeMetadata=structuredClone(freePolicy==='v3_recovery'?recoveryManifest:{revision:result.revision,campaignId:result.campaign.id,sourceSha256:result.sourceSha256,controllerSha256:result.controllerSha256,kind:'cem_training'});freeMetadata.executionStatus='starting';playing=false;$('#play').textContent=tr("播放对照","Play comparison");freeRunning=false;busy=true;runId++;latestTiming=null;roundTrip=[];$('#timing-state').textContent=tr("等待本次计算…","Waiting for computation…");freeFrames=[];events=[];$('#pause-free').disabled=$('#step-free').disabled=$('#impulse').disabled=true;$('#export-free').disabled=true;$('#run-free').disabled=true;$('#engine-state').textContent=tr("加载物理引擎并创建新世界…","Loading the physics engine and creating a new world…");initWorker();worker.postMessage({type:'start',runId,config:freeConfig,params:freeParameters,settings:freePolicy==='v3_recovery'?recoveryManifest.settings:undefined,case:freeCase,policy:freePolicy});}
async function renderFanProbe(){try{const response=await fetch('simulation_v2/fan-grip-probe.json');if(!response.ok)return;const data=await response.json();$('#fan-probe').innerHTML=tr("<h3>风扇确实增加轮胎载荷吗？</h3><p class=\"small\">同一静置初态，显式选择落稳模式的 MuJoCo 台架记录；不是训练成功率。风扇只做姿态力矩补偿，轴向反作用与吸附下压力均保留。</p><div class=\"table-scroll\"><table><tr><th>风扇命令</th><th>轮胎法向载荷</th><th>吸附下压力</th><th>喷口向上补偿</th><th>实际流体功率</th></tr>","<h3>Does the fan actually increase tire load?</h3><p class=\"small\">MuJoCo bench records from the same resting initial state with landing-settle mode selected explicitly; not training success rates. The fan only compensates attitude torque; axial reaction and suction downforce are both retained.</p><div class=\"table-scroll\"><table><tr><th>Fan command</th><th>Tire normal load</th><th>Suction downforce</th><th>Upward nozzle compensation</th><th>Actual fluid power</th></tr>")+data.rows.map(r=>`<tr><td>${round(r.fanCommand*100,0)}%</td><td>${round(r.wheelNormalForce/1000)} kN</td><td>${round(r.suctionForce/1000)} kN</td><td>${round(r.jetForceWorld?.[2]??r.jetVerticalForce,0)} N</td><td>${round(r.fluidPower/1000)} kW</td></tr>`).join('')+'</table></div>';}catch(e){console.warn('Fan bench unavailable',e.message)}}

